with recent_departments as (select * from departments where budget between 2167000 and 3617000 and location not in ('Bangkok', 'Berlin', 'New York') and budget < 4011000), departments_stats as (select dept_name, round((100 * sum(case when location = 'New York' then 1 else 0 end)) / count(*), 1) as pct_new_york, count(distinct budget) as unique_dept_names from recent_departments group by dept_name) select dept_name, pct_new_york, unique_dept_names from departments_stats order by 1
